WITH flattened_attrs AS (SELECT id, plan, currency, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT plan, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, MAX(entry_price) AS max_entry_price, ROUND(SUM(entry_price) / NULLIF(COUNT(CASE WHEN plan = 'starter' THEN 1 END), 0), 2) AS entry_price_per_starter, ROUND(AVG(entry_price), 2) AS avg_entry_price, COUNT(DISTINCT plan) AS distinct_plans, SIZE(COLLECT_SET(currency)) AS num_currencies FROM flattened_attrs GROUP BY ROLLUP (plan) ORDER BY plan
